Here is the commit message:
wifi: mac80211: drop stray 'static' from fast-RX rx_result

ieee80211_invoke_fast_rx() is documented as safe for parallel RX, but
its per-invocation rx_result is declared static. Concurrent callers then
share one instance and can overwrite each other's result between
ieee80211_rx_mesh_data() and the switch on res.

That can make a packet that was queued or consumed by
ieee80211_rx_mesh_data() fall through into ieee80211_rx_8023(), or make
a packet that should continue return as queued.

Make res an automatic variable so each invocation keeps its own result.

Fixes: 3468e1e0c639 ("wifi: mac80211: add mesh fast-rx support")
Cc: stable@vger.kernel.org
Signed-off-by: Catherine <enderaoelyther@gmail.com>
Link: https://patch.msgid.link/20260424131435.83212-2-enderaoelyther@gmail.com
Signed-off-by: Johannes Berg <johannes.berg@intel.com>

Here is the root cause:
The variable `res` in `ieee80211_invoke_fast_rx()` was declared `static`, causing concurrent callers to share one instance. This led to race conditions where one caller's result could be overwritten by another between function calls and the subsequent switch statement, resulting in incorrect packet handling (e.g., a packet queued or consumed by mesh data could fall through to other processing, or a packet that should continue could be incorrectly marked as queued).

Here is the patch:

 static bool ieee80211_invoke_fast_rx(struct ieee80211_rx_data *rx,
 				     struct ieee80211_fast_rx *fast_rx)
 {
 	struct sk_buff *skb = rx->skb;
 	struct ieee80211_hdr *hdr = (void *)skb->data;
 	struct ieee80211_rx_status *status = IEEE80211_SKB_RXCB(skb);
-	static ieee80211_rx_result res;
+	ieee80211_rx_result res;
 	int orig_len = skb->len;
 	int hdrlen = ieee80211_hdrlen(hdr->frame_control);
 	int snap_offs = hdrlen;
 	struct {
 		u8 snap[sizeof(rfc1042_header)];
 		__be16 proto;
 	} *payload __aligned(2);
 	struct {
 		u8 da[ETH_ALEN];
 		u8 sa[ETH_ALEN];
 	} addrs __aligned(2);
 	struct ieee80211_sta_rx_stats *stats;

 	/* for parallel-rx, we need to have DUP_VALIDATED, otherwise we write
 	 * to a common data structure; drivers can implement that per queue
 	 * but we don't have that information in mac80211
 	 */
 	if (!(status->flag & RX_FLAG_DUP_VALIDATED))
 		return false;

 #define FAST_RX_CRYPT_FLAGS	(RX_FLAG_PN_VALIDATED | RX_FLAG_DECRYPTED)

 	/* If using encryption, we also need to have:
 	 *  - PN_VALIDATED: similar, but the implementation is tricky
 	 *  - DECRYPTED: necessary for PN_VALIDATED
 	 */
 	if (fast_rx->key &&
 	    (status->flag & FAST_RX_CRYPT_FLAGS) != FAST_RX_CRYPT_FLAGS)
 		return false;

 	if (unlikely(!ieee80211_is_data_present(hdr->frame_control)))
 		return false;

 	if (unlikely(ieee80211_is_frag(hdr)))
 		return false;

 	/* Since our interface address cannot be multicast, this
 	 * implicitly also rejects multicast frames without the
 	 * explicit check.
 	 *
 	 * We shouldn't get any *data* frames not addressed to us
 	 * (AP mode will accept multicast *management* frames), but
 	 * punting here will make it go through the full checks in
 	 * ieee80211_accept_frame().
 	 */
 	if (!ether_addr_equal(fast_rx->vif_addr, hdr->addr1))
 		return false;

 	if ((hdr->frame_control & cpu_to_le16(IEEE80211_FCTL_FROMDS |
 					      IEEE80211_FCTL_TODS)) !=
 	    fast_rx->expected_ds_bits)
 		return false;

 	/* assign the key to drop unencrypted frames (later)
 	 * and strip the IV/MIC if necessary
 	 */
 	if (fast_rx->key && !(status->flag & RX_FLAG_IV_STRIPPED)) {
 		/* GCMP header length is the same */
 		snap_offs += IEEE80211_CCMP_HDR_LEN;
 	}

 	if (!ieee80211_vif_is_mesh(&rx->sdata->vif) &&
 	    !(status->rx_flags & IEEE80211_RX_AMSDU)) {
 		if (!pskb_may_pull(skb, snap_offs + sizeof(*payload)))
 			return false;

 		payload = (void *)(skb->data + snap_offs);

 		if (!ether_addr_equal(payload->snap, fast_rx->rfc1042_hdr))
 			return false;

 		/* Don't handle these here since they require special code.
 		 * Accept AARP and IPX even though they should come with a
 		 * bridge-tunnel header - but if we get them this way then
 		 * there's little point in discarding them.
 		 */
 		if (unlikely(payload->proto == cpu_to_be16(ETH_P_TDLS) ||
 			     payload->proto == fast_rx->control_port_protocol))
 			return false;
 	}

 	/* after this point, don't punt to the slowpath! */

 	if (fast_rx->uses_rss)
 		stats = this_cpu_ptr(rx->link_sta->pcpu_rx_stats);
 	else
 		stats = &rx->link_sta->rx_stats;

 	if (rx->key && !(status->flag & RX_FLAG_MIC_STRIPPED) &&
 	    pskb_trim(skb, skb->len - fast_rx->icv_len))
 		goto drop;

 	if (rx->key && !ieee80211_has_protected(hdr->frame_control))
 		goto drop;

 	if (status->rx_flags & IEEE80211_RX_AMSDU) {
 		if (__ieee80211_rx_h_amsdu(rx, snap_offs - hdrlen) !=
 		    RX_QUEUED)
 			goto drop;

 		return true;
 	}

 	/* do the header conversion - first grab the addresses */
 	ether_addr_copy(addrs.da, skb->data + fast_rx->da_offs);
 	ether_addr_copy(addrs.sa, skb->data + fast_rx->sa_offs);
 	if (ieee80211_vif_is_mesh(&rx->sdata->vif)) {
 	    skb_pull(skb, snap_offs - 2);
 	    put_unaligned_be16(skb->len - 2, skb->data);
 	} else {
 	    skb_postpull_rcsum(skb, skb->data + snap_offs,
 			       sizeof(rfc1042_header) + 2);

 	    /* remove the SNAP but leave the ethertype */
 	    skb_pull(skb, snap_offs + sizeof(rfc1042_header));
 	}
 	/* push the addresses in front */
 	memcpy(skb_push(skb, sizeof(addrs)), &addrs, sizeof(addrs));

 	res = ieee80211_rx_mesh_data(rx->sdata, rx->sta, rx->skb);
 	switch (res) {
 	case RX_QUEUED:
 		stats->last_rx = jiffies;
 		stats->last_rate = sta_stats_encode_rate(status);
 		return true;
 	case RX_CONTINUE:
 		break;
 	default:
 		goto drop;
 	}

 	ieee80211_rx_8023(rx, fast_rx, orig_len);

 	return true;
  drop:
 	dev_kfree_skb(skb);

 	stats->dropped++;
 	return true;
 }



